"""Prototype coverage counts use measured REASONING scale, never input size."""
import math

def scale_bin(value,bins):
    if isinstance(value,bool) or not isinstance(value,(int,float)) or not math.isfinite(value):return None
    for i,(lo,hi) in enumerate(bins):
        if lo<=value<hi or (i==len(bins)-1 and value==hi):return i
    return None

def summarize(catalog,policy):
    bins=policy['scale_bins_nm'];cells=[]
    for domain in policy['domains']:
        for index,span in enumerate(bins):
            located=[q for q in catalog['questions'] if q['domain']==domain and scale_bin(q.get('reasoningSizeNm'),bins)==index]
            screened=[q for q in located if q.get('lifecycle','active')=='active' and q.get('prototypeScreeningPassed') is True and q.get('status')=='pending_human_audit']
            counts={a:sum(q['ability']==a for q in screened) for a in policy['ability_soft_targets']}
            cells.append({'domain':domain,'range_nm':span,'target':policy['target_per_cell'],'located_candidates':len(located),'screened_count':len(screened),'remaining':max(0,policy['target_per_cell']-len(screened)),'abilities':counts,'ability_shortfalls':{a:max(0,n-counts[a]) for a,n in policy['ability_soft_targets'].items()},'qa_ids':[q['id'] for q in screened],'blocker':'Still missing validated task/material coverage; absence is not proof the task is impossible.' if len(screened)<policy['target_per_cell'] else ''})
    return {'version':policy['version'],'primary_scale':'reasoning','target_total':len(cells)*policy['target_per_cell'],'screened_total':sum(c['screened_count'] for c in cells),'formal_ready':catalog['counts']['ready'],'unlocated_candidates':sum(scale_bin(q.get('reasoningSizeNm'),bins) is None for q in catalog['questions']),'note':'Same-session prototype screening, not expert certification. Historical candidates are not automatically grandfathered in.','cells':cells}

from pathlib import Path

def check_units(b, units, bundle):
    b.validate(units, b.read(Path(__file__).with_name('schema.json')))
    sources = b.bundle_check(bundle)
    for asset in b.unique(units['assets'], 'source_id').values():
        if asset['source_id'] not in sources or sources[asset['source_id']]['kind'] != 'xyz':
            raise ValueError('units: unknown XYZ asset')
        if asset['unit'] == 'angstrom':
            if not asset['checked_by'].strip():
                raise ValueError('units: missing checker identity')
            b.check_refs(asset['source_refs'], sources)
        elif asset['source_refs']:
            b.check_refs(asset['source_refs'], sources)

def prepare(b, args):
    sources=[]; warnings=[]
    for filename in args.source:
        path=Path(filename)
        if path.suffix.lower()=='.pdf':
            try: from pypdf import PdfReader
            except ImportError: raise ValueError('PDF requires pypdf; alternatively supply extracted UTF-8 text')
            warnings.append(path.name+': text-only PDF extraction; images and table layout NOT validated')
            chunks=[(f'page {i+1}',page.extract_text() or '') for i,page in enumerate(PdfReader(path).pages)]
        else:
            lines=path.read_text(encoding='utf-8-sig').splitlines()
            chunks=[(f'lines {i+1}-{min(i+60,len(lines))}','\n'.join(lines[i:i+60])) for i in range(0,len(lines),60)]
        for loc,text in chunks:
            if not text.strip(): warnings.append(path.name+' '+loc+': empty'); continue
            sources.append({'source_id':f'S{len(sources)+1:04}','location':path.name+' '+loc,'origin':str(path.resolve()),'kind':'text','text':text})
    for filename in args.xyz:
        path=Path(filename); text=path.read_text(encoding='utf-8-sig'); b.parse_xyz(text)
        sources.append({'source_id':f'S{len(sources)+1:04}','location':path.name+' XYZ (unit recorded separately)','origin':str(path.resolve()),'kind':'xyz','text':text})
    bundle={'paper_id':args.paper_id,'title':args.title,'url':args.url,'synthetic':args.synthetic,'sources':sources,'warnings':warnings}
    b.bundle_check(bundle)
    if Path(args.out).exists(): raise ValueError('output already exists; choose a new file')
    b.write(args.out,bundle)

